--   staff_resignation_received   the Admins and Finance: who, the last day, the reason, what went back to the queue
--   staff_resignation_withdrawn  the Admins and Finance: the resignation was withdrawn before the last day
-- The catalogue block is generated by supabase/seed/5021_gen_catalogue.mjs. SCHEMA_MARKER 5022.
set local check_function_bodies = off;

create function pg_temp.patch_fn(p_sig regprocedure, p_old text, p_new text) returns void
language plpgsql as $$
declare d text := pg_get_functiondef(p_sig);
begin
  if position(p_old in d) = 0 then raise exception '5021: the text to change was not found in %: %', p_sig, left(p_old, 160); end if;
  execute replace(d, p_old, p_new);
end $$;

